DB_PATH = Path(os.environ.get("SH_DB", "sparinghorse.db"))
RUNALYZE_BASE = os.environ.get("RUNALYZE_BASE", "https://runalyze.com/api/v1")
RUNALYZE_TOKEN = os.environ.get("RUNALYZE_TOKEN", "")  # personal API token (token: header)
